#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> wordCount;  // Map to count word occurrences
    std::string word = "apple";

    // Practical usage: Increment count, but insert if not present
    if (wordCount.find(word) != wordCount.end()) {
        wordCount[word]++;  // Key exists, safely increment
    } else {
        wordCount[word] = 1;  // Key doesn't exist, this inserts and sets to 1
    }

    // Alternative: Using insert for safer, non-overwriting addition
    auto result = wordCount.insert({word, 1});  // Inserts only if key absent
    if (!result.second) {  // Key already existed
        result.first->second++;  // Increment the existing value
    }

    std::cout << "Count of '" << word << "': " << wordCount[word] << std::endl;
    return 0;
}
